S=/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/a3cc81de-9d62-45b3-a48c-553e0275bc00/scratchpad && cat > $S/urlrepro.ps1 <<'EOF'
# Does launching this JusPrin take over HKCU's orcaslicer:// handler?
# Sets the handler to a stand-in "real OrcaSlicer", launches the app with its
# own data dir, watches the value, stops only the process it started, and puts
# the original value back.
param([string]$Exe, [string]$DataDir, [int]$Seconds = 150)
$ErrorActionPreference = "Stop"
$k = 'HKCU:\Software\Classes\orcaslicer\shell\open\command'
$fake = '"C:\FakeOrca\orca-slicer.exe" "%1"'
$saved = 'C:\guitest\urlrepro\original-orcaslicer-command.txt'
New-Item -ItemType Directory -Force C:\guitest\urlrepro | Out-Null
if (-not (Test-Path $saved)) {
    if (Test-Path $k) { Set-Content $saved ((Get-ItemProperty $k).'(default)') } else { Set-Content $saved '<absent>' }
}
"original value: " + (Get-Content $saved)
if (-not (Test-Path $k)) { New-Item -Force $k | Out-Null }
Set-Item $k -Value $fake
"set to stand-in: " + (Get-ItemProperty $k).'(default)'

if (Test-Path $DataDir) { Remove-Item -Recurse -Force $DataDir }
New-Item -ItemType Directory -Force $DataDir | Out-Null
$env:GALLIUM_DRIVER = 'llvmpipe'; $env:LIBGL_ALWAYS_SOFTWARE = '1'
$p = Start-Process -FilePath $Exe -ArgumentList "--datadir `"$DataDir`"" -WorkingDirectory (Split-Path $Exe) -PassThru
"started pid $($p.Id): $Exe"
$value = $fake
for ($i = 0; $i -lt $Seconds; $i += 2) {
    Start-Sleep 2
    $value = (Get-ItemProperty $k).'(default)'
    if ($value -ne $fake) { "changed after ${i}s"; break }
    if ($p.HasExited) { "process exited after ${i}s with code $($p.ExitCode)"; break }
}
"value now: $value"
"--- app log (last lines)"
Get-ChildItem "$DataDir\log" -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1 | ForEach-Object { Get-Content $_.FullName -Tail 8 }
if (-not $p.HasExited) { Stop-Process -Id $p.Id -Force; "stopped pid $($p.Id)" }
$orig = Get-Content $saved
if ($orig -eq '<absent>') { Remove-Item -Recurse -Force 'HKCU:\Software\Classes\orcaslicer' } else { Set-Item $k -Value $orig }
"restored: " + $(if (Test-Path $k) { (Get-ItemProperty $k).'(default)' } else { '<absent>' })
EOF
