    for ($i = 0; $i -lt $seconds; $i++) {
        $r = & $test; if ($r) { return $r }
        if ($i % 15 -eq 0) { Log ("  waiting for $what; windows: " + ((Windows-Of $p.Id | ForEach-Object { "[" + $_.Value + "]" }) -join ' ')) }
        Start-Sleep 1
    }
    throw "timed out after ${seconds}s waiting for $what"
}

