    [System.Windows.Forms.SendKeys]::SendWait("^p")''')
s=s.replace('''$jp = Wait-For "JusPrin Preferences" 60 { Windows-Of $p.Id | Where-Object { $_.Current.Name -eq 'Preferences' } | Select-Object -First 1 }
    Log "JusPrin Preferences open"''',
