    }''',
'''$orcaw = Wait-For "OrcaSlicer Preferences" 60 { Windows-Of $p.Id | Where-Object { $_.Value -eq 'Preferences' -and $_.Key -ne $jpw.Key } | Select-Object -First 1 }
    $orca = $UIA::FromHandle($orcaw.Key)''')
s=s.replace('''Wait-For "OrcaSlicer Preferences to close" 30 { -not (Windows-Of $p.Id | Where-Object { $_.Current.Name -eq 'Preferences' }) } | Out-Null''',
'''Wait-For "OrcaSlicer Preferences to close" 30 { -not (Windows-Of $p.Id | Where-Object { $_.Value -eq 'Preferences' }) } | Out-Null''')
open(p,'w').write(s)
PYEOF
grep -n "Current.Name\|\$_.Current" $S/prefs-close.ps1

